      System.out.println(e);
    }
  }

  public static int getPrimeNumber(int array[]){
	  int total = 0;
	  for(int i = 0;i < array.length;++i){
		  boolean isPrime = true;
		  if(array[i] % 2 == 0){
			  isPrime = false;
		  }
		  else{
			//for(int j = 3;j <= Math.sqrt(array[i]);j += 2)
			  for(int j = 3;j < array[i];j += 2){
				if(array[i] % j == 0){
					isPrime = false;
					break;
				}
			}
		  }
		  if(isPrime || array[i] == 1)total++;
	  }
	  return total;
  }
}

