import static java.lang.System.out;

class SortingThreeNumbers {

    public static int[] sorted( int[] inputs) {
        int[] res = Arrays.copyOf( inputs, inputs.length );

        for ( int i = 0; i < res.length; i++ ) {
            for ( int j = 1; j < res.length - i; j++ ) {
                if ( res[j - 1] > res[j] ) {
                    int tmp = res[j - 1];
                    res[j - 1] = res[j];
                    res[j] = tmp;
                }
            }
        }

        return res;
    }

}

