        int Y = scanner.nextInt();

        int sum1, sum2, sum3;
        for (int s=N; s >= 0; s--) {
            // 10,000
            sum1 = 10000 * s;
            if (sum1 > Y) {
                continue;
            }
            for (int t=N - s; t >= 0; t--) {
                // 5,000
                sum2 = 5000 * t;
                if (sum1 + sum2 > Y) {
                    continue;
                }

                // 1,000
                int u = N - s - t;
                sum3 = 1000 * u;
