		int N = sc.nextInt();

		// Aiの入力
		ArrayList<Integer> a = new ArrayList<>();
		for (int i = 0; i < N; i++) {
			a.add(sc.nextInt());
		}

		// Biは最初に全部合計しておく
		int sum = 0;
