public class Main {
  static InputReader in;
  static PrintWriter out;

  static class Solution {
    void solve() throws IOException {
      while (true) {
        int n = in.nextInt();
        if (n == 0) {
          break;
        }
        double variance = 0;
        double stddev;
        int sum = 0;
        double avg;

        int[] score = new int[n];
        for (int i = 0; i < n; i++) {
          score[i] = in.nextInt();
          sum += score[i];
        }
        avg = sum / n;

        for (int i = 0; i < n; i++) {
          variance += Math.pow(score[i] - avg, 2);
        }
        variance /= n;

        stddev = Math.sqrt(variance);
        out.printf("%.5f\n", stddev);
      }


//      End solve()
    }
//    End Solution
}


