    static class BPopularVote {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.readInt();
            int m = in.readInt();

            int[] a = new int[n];
            double sum = 0.0;
            for (int i = 0; i < n; i++) {
                a[i] = in.readInt();
                sum += a[i];
            }

            int sel = 0;
            for (int i = 0; i < n; i++) {
                if (a[i] >= sum * 1.0 / (4 * m))
                    sel++;
            }
            System.out.println(sel >= m ? "Yes" : "No");

        }

    }

