          A[j+1] = A[j];
          j--;
        }
        A[j+1] =v;

        for (int k = 0; k < N; k++) {
          out.print(A[k]);
          if (k != N - 1) {
            out.print(" ");
          } else {
            out.print("\n");
          }
        }
      }

