				if((k - list.get(n - 1)) + list.get(0) > count) {
					count = (k - list.get(n - 1)) + list.get(0);
				}
			}else {
				if((list.get(i) - list.get(i - 1)) > count) {
					count = list.get(i) - list.get(i - 1);
				}
			}
		}

		System.out.println(k - count);
	}
