			}
		}
		System.out.println(count);
	}


	public static void makePrimeList(int n) {
		isntPrime = new boolean[n+1];
		isntPrime[0] = isntPrime[1] = true;
		for(int i = 3; i < n; i+=2) {
			if(!isntPrime[i]) {
				for(int j = i + i; j < n; j += i){
					isntPrime[j] = true;
				}
			}
		}
	}
}

