import java.util.Scanner;

public class Main{

	/**
	 * 2つの自然数x,yを入力とし、それらの最大公約数を求めるプログラム
	 * 
	 * @param args
	 */
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int x = scan.nextInt();
		int y = scan.nextInt();

		System.out.println(Gcd(x, y));

	}

	/**
	 * 最大公約数をもとめる
	 * 
	 * @param x
	 *            入力１
	 * @param y
	 *            入力２（x%y)
	 * @return 最大公約数
	 */
	public static int Gcd(int x, int y) {
		if (y > x) {
			int tmp;
			tmp = x;
			x = y;
			y = tmp;
		}

		if (y == 0) {
			return x;
		} else {
			return Gcd(y, x % y);
		}
	}
}

import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * AtCoder Beginner Contest 129<br>
 * B - Balance<br>
 * <br>
 * <a href=
 * "https://atcoder.jp/contests/abc129/tasks/abc129_b">AtCoderへのリンク</a><br>
 */
public class Main {

	/**
	 * エントリポイント
	 */
	public static void main(String[] args) {
		// 入力
		Model m = input(System.in);
		// 演算
		int result = proc(m);
		// 出力
		System.out.println(result);
	}

	/**
	 * 入力モデル
	 */
	static class Model {
		/** オモリの数 */
		int N;
		/** オモリの重さリスト */
		List<Integer> list = new ArrayList<Integer>();
	}

	/**
	 * 入力値より入力モデルを作成する
	 */
	private static Model input(InputStream in) {
		Model m = new Model();
		try (Scanner sc = new Scanner(in)) {
			String[] line1 = sc.nextLine().split(" ");
			String[] line2 = sc.nextLine().split(" ");

			m.N = Integer.parseInt(line1[0]);
			for (String str : line2) {
				m.list.add(Integer.parseInt(str));
			}
		}
		return m;
	}

	/**
	 * 演算を行う
	 */
	static int proc(final Model m) {
		int min = Integer.MAX_VALUE;

		for (int i = 1; i < m.N; i++) {
			int s1 = sumAll(m.list.subList(0, i));
			int s2 = sumAll(m.list.subList(i, m.list.size()));

			min = Math.min(min, Math.abs(s1 - s2));
		}
		return min;
	}

	static int sumAll(List<Integer> list) {
		int sum = 0;
		for (int item : list) {
			sum += item;
		}
		return sum;
	}
}

