	public static boolean isFixed(int[] arr, int[] arr2) {
		boolean flag = false;
		for (int count = 0; count < arr.length; count++) {
			if(arr[count] != arr2[count]) {
				flag = false;
				break;
			}
			else {
				flag = true;
			}
		}
		return flag;
	}

    public static int[] swap(int x, int y, int[] arr) {
		int a = arr[x];
		int b = arr[y];
		arr[x] = b;
		arr[y] = a;
		return arr;
	}


