		int ar[] = new int[n];
		for(int i = 0; i < n; i++) {
			ar[i] = Integer.parseInt(input2[i]);
		}
		int dp[] = new int[n];
		for(int i = n - 1; i >= 0; i--) {
			if(i == n - 1) {
				dp[i] = 0;
				continue;
			}
			// dp[i][0] : one step
			// dp[i][1] : two step
			dp[i] = MAX;
			for(int j = 1; j <= k; j++) {
				if(i + j < n) {
					dp[i] = Math.min(dp[i], dp[i + j] + (int) Math.abs(ar[i + j] - ar[i]));
				}
			}
		}
		System.out.println(dp[0]);
	}
}

