		System.out.println(lcm(m, n));
	}

	public static long gcd(Long a, Long b){

		if(b == 0)	return a;
		else return gcd(b, a % b);
	}

	public static long lcm(long a, long b){
		return a * b / gcd(a, b);
	}
}

