    for(int i = 0; i < N; i++){
      B[i] = scanner.nextInt();
    }

    /*
    * 勇者はn番目から倒していくと効率が良い
    * 次の勇者はn番目を倒すことができないから
    */

    int total = 0;

    for(int n = 0; n < N; n++){
      int amount = Math.min(A[n], B[n]);
      B[n] -= amount;
      total += amount;

      amount = Math.min(A[n+1], B[n]);
      total += amount;
    }

    System.out.println(total);
  }
}

