    static void solve(){
        Deque<int[]> que=new ArrayDeque<int[]>();
	int n=ir.nextInt();
	int q=ir.nextInt();
	String[] name=new String[n];
	for(int i=0;i<n;i++){
	    name[i]=ir.next();
	    que.offerLast(new int[]{i,ir.nextInt()});
	}
	int cur=0;
	while(!que.isEmpty()){
	    int[] a=que.pollFirst();
	    if(a[1]<=q){
		cur+=a[1];
		out.println(name[a[0]]+" "+cur);
	    }
	    else{
		cur+=q;
		que.offerLast(new int[]{a[0],a[1]-q});
	    }
	}
    }

