		int n=scan.nextInt();
		int y=scan.nextInt();
		int value[]= {10000,5000,1000};
		int cnt[]= {0,0,0};
		scan.close();
		int flg=0;
		for(int i=0;i<n;i++) {
			for(int j=0;j<n;j++) {
				if(n-i-j>=0) {
					if(value[0]*i+value[1]*j+value[2]*(n-i-j)==y) {
						flg=1;
						cnt[0]=i;
						cnt[1]=j;
						cnt[2]=n-i+j;
						break;
					}
				}
			}
			if(flg==1)break;
		}

		if(flg==0)System.out.println("-1 -1 -1");
		else {
			System.out.println(cnt[0]+" "+cnt[1]+" "+cnt[2]);
		}
	}

