	public static void main(String[] args) {
	Scanner sc= new Scanner(System.in);
	int n = sc.nextInt();
	int i = 1;

	do {
		int x = i;
		if (x % 3 == 0) {
			System.out.print("" + i);
			break;
		}
		while (true) {
		if (x % 10 == 3) {
			System.out.print("" + i);
			break;
		}
		x /= 10;
		if (x != 0) continue;
		else break;
		}
	} while (++i <= n);
	System.out.println();
	}
}

