			if(arr1[i]>=arr2[i]) {
				monster+=arr2[i];
			}
			else {
				if(arr1[i]+arr1[i+1]>=arr2[i]) {
					monster+=arr2[i];
					arr1[i+1]-=arr2[i]-arr1[i];
				}
				else {
					monster+=arr1[i]+arr1[i+1];
					arr1[i+1]=0;
