        }

        String arr01[] = mylist.get(0).split(" ");

        int l = Integer.valueOf(arr01[0]);
        double maxdata = 0;
        int a = 1;
        int b = 1;

        if (l <= 2) {
            maxdata = l;
        } else {

            for (int i = a; i <= l; i++) {
                for (int j = b; j <= l; j++) {
                    if (i + j >= l) {
                        break;
                    }
                    int k = l - i - j;
                    //                System.out.println(i + " " + j + " " + k);
                    if (k > 0) {
                        maxdata = Math.max(maxdata, i * j * k);
                    }
                }
            }
        }

        System.out.println(maxdata);

    }

}

