		 * 素数であるかどうかを判定数
		 * @param check_num	判定する数字
		 * @return				判定結果(true:素数)
		 */
		public static boolean PrimeNumber_Checker(long check_num){

			for(int k = 2; k < check_num;k= k+2){
				if(check_num % k == 0){
					return false;
				}
			}
			return true;

		}
}

