public class Main {

  public static void main(String[] args) { 
      Scanner sc = new Scanner(System.in);
      long n = sc.nextLong();
      long origN = n;
      List<Long> list = new ArrayList<>();
      for(long i = 2; i <= n; i++) {
        while(n > 1 && n % i == 0) {
          list.add(i);
          n /= i;
        }
      }
      long res = 1;
      long minDigit = Integer.MAX_VALUE;
      for(int i = 0; i < (1 << list.size()); i++) {
        long curRes = 1;
        for(int j = 0; j < list.size(); j++) {
          if(((i >> j) & 1) == 1) {
            curRes *= list.get(j);
          }
        }
        minDigit = Math.min(minDigit, calDigit(Math.max(curRes, origN / curRes)));
      }

      System.out.println(minDigit);
  }

  private static long calDigit(long n) {
    long cnt = 0;
    while(n > 0) {
      cnt++;
      n /= 10;
    }
    return cnt;
  } 
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static int quantum;
    public static int currentTime = 0;
    public Main() {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        int quantum = scan.nextInt();

        Queue queue = new Queue(100 + n);
        this.quantum = quantum;

        while(scan.hasNext()){
            String pName = scan.next();
            int time = scan.nextInt();
            queue.enqueue(new Data(pName, time));
        }
        while(!queue.isEmpty()){
            Data data = queue.dequeue();
            if(data.time == 0){
                System.out.println(data.pName + " " + currentTime);
            }
        }
    }

    public static void main(String[] args) {
        new Main();
    }

    private class Queue{
        private int head = 0;
        private int tail = 0;
        private Data queue[];

        public Queue(int size){
            queue = new Data[size*2];
        }

        public void enqueue(Data data){
            queue[tail++] = data;
        }

        public Data dequeue(){
            Data data = queue[head++];
            int time = expendedTime(data);
            if(data.time != 0){
                enqueue(data);
            }
            currentTime += time;
            return data;
        }

        public int expendedTime(Data data){
            int time;
            if(data.time > quantum){
                time = quantum;
                data.time -= quantum;
            }else{
                time = data.time;
                data.time = 0;
            }
            return time;
        }

        public boolean isEmpty(){
            return head == tail;
        }

    }

    private class Data{
        public String pName;
        public int time;

        public Data(String pName, int time){
            this.pName = pName;
            this.time = time;
        }
    }
}

