		int q = sc.nextInt();

		char[] s = sc.next().toCharArray();
		int[] cumsuma = new int[n + 1];
		int[] cumsumc = new int[n + 1];
		for (int i = 0; i < n; i++) {
			if (i + 1 < n) {
				cumsuma[i + 1] = cumsuma[i] + (s[i] == 'A' && s[i + 1] == 'C' ? 1 : 0);
			}
			if (i > 0) {
				cumsumc[i + 1] = cumsumc[i] + (s[i] == 'C' && s[i - 1] == 'A' ? 1 : 0);
			}
		}

		for (int i = 0; i < q; i++) {
			int l = sc.nextInt() - 1;
			int r = sc.nextInt() - 1;

			pr.println(cumsumc[r + 1] - cumsuma[l]);
		}
	}

