	public static int fun(int ind) {
		if(ind == n-1) return 0; 
		int max = (int) 1e5 + 7; 
		if(dp[ind] != -1) return dp[ind]; 
		for(int i = 1; i<=k; i++) {
			if(ind + i < n)
			max = Math.min(max, Math.abs(a[ind + i] - a[ind]) + fun(ind + i)); 
		}
		return dp[ind] = max; 
	}
