	public static void sort(int[][] x,int n) {
		for(int i=0;i<n-1;i++) {
			for(int j=0;j<n-1;j++) {
				if(x[j][0]>x[j+1][0]) {
					int temp = x[j][0];
					x[j][0] = x[j+1][0];
					x[j+1][0] = temp;

					temp = x[j][1];
					x[j][1] = x[j+1][1];
					x[j+1][1] = temp;
				}
			}
		}
	}
