        int n = in.nextInt();
        int q = in.nextInt();
        String str = in.nextLine();
        int[] pre = new int[n];
        pre[0] = 0;
        for (int i=1; i<n; i++) {
            if (str.charAt(i - 1) == 'A' && str.charAt(i) == 'C') {
                pre[i] = pre[i - 1] + 1;
            } else {
                pre[i] = pre[i - 1];
            }
        }
        while(q-- > 0) {
            int l = in.nextInt();
            int r = in.nextInt();
//            out.println(l == 1 ? pre[r - 1]: (str.charAt(l - 1) == 'C' && str.charAt(l) == 'A' ?
//                    pre[r - 1] - pre[l - 2] - 1: pre[r - 1] - pre[l - 2]));
            if (l == 1) {
                out.println(pre[r - 1]);
            } else {
                if (str.charAt(l - 1) == 'C' && str.charAt(l) == 'A') {
                    out.println(pre[r - 1] - pre[l - 2] - 1);
                } else {
                    out.println(pre[r - 1] - pre[l - 2]);
                }
            }
        }
        out.close();
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public Scanner(String s) {
            try {
                br = new BufferedReader(new FileReader(s));
            } catch (FileNotFoundException e) {
                e.printStackTrace();
            }
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public double[] nextDoubleArray(int n) {
            double[] arr = new double[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextDouble();
            }
            return arr;
        }

        public long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        public char[] nextCharArray(int n) {
            char[] arr = nextLine().trim().replaceAll("\\s", "").toCharArray();
            return arr;
        }

        public String[] nextStringArray(int n) {
            String[] arr = new String[n];
            for (int i = 0; i < n; i++) {
                arr[i] = next();
            }
            return arr;
        }
    }
}

