		int N = sc.ni();
		int[] next = new int[N];
		for (int i = 0; i < N; i++)
			next[i] = sc.ni()-1;

		int[] dist = new int[N];
		Arrays.fill(dist,-1);
		dist[0] = 0;
		ArrayDeque<Integer> bfs = new ArrayDeque<Integer>();
		bfs.add(0);
		while (!bfs.isEmpty()) {
			int node = bfs.poll();
			if (dist[next[node]] == -1) {
				bfs.add(next[node]);
				dist[next[node]] = dist[node]+1;
			}
		}

		pw.println(dist[1]);

		pw.close();
	}


	public static long dist(long[] p1, long[] p2) {
		return (Math.abs(p2[0]-p1[0])+Math.abs(p2[1]-p1[1]));
	}

	//Find the GCD of two numbers
	public static long gcd(long a, long b) {
		if (a < b) return gcd(b,a);
		if (b == 0)
			return a;
		else
			return gcd(b,a%b);
	}

	//Fast exponentiation (x^y mod m)
	public static long power(long x, long y, long m) { 
		if (y < 0) return 0L;
		long ans = 1;
		x %= m;
		while (y > 0) { 
			if(y % 2 == 1) 
				ans = (ans * x) % m; 
			y /= 2;  
			x = (x * x) % m;
		} 
		return ans; 
	}

