/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        BBiteEating solver = new BBiteEating();
        solver.solve(1, in, out);
        out.close();
    }

    static class BBiteEating {
        public void solve(int testNumber, FastReader s, PrintWriter out) {
            int n = s.nextInt();
            int l = s.nextInt();

            int sum = 0;
            TreeSet<Integer> negatives = new TreeSet<>();
            TreeSet<Integer> positives = new TreeSet<>();
            for (int i = 0; i < n; i++) {
                sum += (l + i);
                if (l + i < 0) {
                    negatives.add(l + i);
                } else {
                    positives.add(l + i);
                }
            }

            if (positives.contains(0)) {
                out.println(sum);
            } else {
                if (negatives.isEmpty()) {
                    out.println(sum - positives.first());
                } else if (positives.isEmpty()) {
                    out.println(sum - negatives.last());
                } else {
                    if (Math.abs(negatives.last()) < positives.first()) {
                        out.println(sum - negatives.last());
                    } else {
                        out.println(sum + positives.first());
                    }
                }
            }


        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastReader.SpaceCharFilter filter;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

