                    for (int i = 0; i < m; i++) {
                        matrix_a[l][i] = Integer.parseInt(st.nextToken());
                    }
                    l++;
                }
            } else {
                while (st.hasMoreTokens()) {
                    matrix_b[a] = Integer.parseInt(st.nextToken());
                    a++;
                }
            }
            if(l == n && a == m) break;
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int num1 = matrix_a[i][j];
                int num2 = matrix_b[j];
                int ans = num1 * num2; 
                matrix_ans[i] += ans;
            }
        }

        for (int i = 0; i < n; i++) {
            System.out.println(matrix_ans[i]);
