                ans = 0L;
                break;
            } else {
                int len = a[i] - a[i - 1] - 1;
                for (int j = fibList.size(); j <= len; j++) {
                    fibList.add(fibList.get(j - 2) + fibList.get(j - 1));
                }
                ans*=fibList.get(len - 1);
                ans%=1_000_000_007L;
            }
        }
        System.out.println(ans);
    }
}

