		long A = scn.nextLong();
		long B = scn.nextLong();
		long C = scn.nextLong();
		long D = scn.nextLong();
		long ans = B - A + 1;
		long ansC = 0, ansD = 0, ansCD = 0;
		long CD = lcm(C,D);
		if (A == B) {
			System.out.println((A % C == 0) || (A % D == 0) ? 0 : 1);
		} else {
			if (C == D) {
				if (C <= B) {
					if (A % C == 0) {
						ansC = (B - A) / C + 1;
					} else {
						ansC = (B - (A + (C - A % C))) / C + 1;
					}
				}
			} else {
				if (C <= B) {
					if (A % C == 0) {
						ansC = (B - A) / C + 1;
					} else {
						ansC = (B - (A + (C - A % C))) / C + 1;
					}
				}
				if (D <= B) {
					if (A % D == 0) {
						ansD = (B - A) / D + 1;
