public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		int k = ir.nextInt();
		int x = ir.nextInt();
		for (int i = x - k + 1; i < x + k; i++) {
			out.print(i + (i == x + k - 1 ? "\n" : " "));
