class Solver {
    public void solve(long N, long X, long[] L) {
        if (X == 0) {
            System.out.println(0);
            return;
        }

        long D = 0;
        for (int i = 0; i < N; i++) {
            D += L[i];
            if (D > X) {
                System.out.println(i + 1);
                return;
            }
        }

        System.out.println(N+1);
    }
}

