import java.io.*;
import java.util.*;

class Main{
    public static void main(String args[])throws IOException{
      try(BufferedReader br = new BufferedReader(new InputStreamReader(System.in))){
        //input
        String[] num  = br.readLine().split(" ");        
        int A = Integer.parseInt(num[0]);
        int B = Integer.parseInt(num[1]);

        //for algorithm
        long result = 1;
        int count_A = 0, count_B = 0;
        int count_big_A = 0, count_big_B = 0;
        int max = 100000;
        int prime_max = (int)Math.sqrt(max);
        boolean[] table = new boolean[max+1];
        List<Integer> prime = new  ArrayList<>();

        Arrays.fill(table, true);

        table[0] = table[1] = false;
        int count = 0;

        for(int i = 2; i <= prime_max; i++){
          if(table[i]){
            prime.add(i);
            count++;
            int j = i + i;
            while(j <= max){
              table[j] = false;
              j = j + i;
            }
          }
        }



        //algorithm
        for(int i = 0; i < prime.size(); i++){
          if(A < prime.get(i) && B < prime.get(i)){
            break;
          }

          count_A = count_B = 0;

          while( A%prime.get(i) == 0){
            A /= prime.get(i);
            count_A++;
            count_big_A++;
          }

          while( B%prime.get(i) == 0){
            B /= prime.get(i);
            count_B++;
            count_big_B++;
          }

          if(count_A != 0 || count_B != 0){
            result *= (long)Math.pow((double)prime.get(i), (double)Math.max(count_A, count_B));
          }
        }

        if(count_big_A == 0){
          result *= A;
        }

        if(count_big_B == 0){
          result *= B;
        }

        System.out.println(result);
      }

    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Scanner;
import java.util.TreeMap;

public class Main {

	public static void main(String[] args) {
		Scanner s = new Scanner(System.in);
		int n = s.nextInt(), m = s.nextInt();
		Map<Integer,String> ac = new TreeMap<>();
		Map<Integer,String> wa = new TreeMap<>();
		Map<String, Integer> waMap = new HashMap<String, Integer>();
		int wrong = 0, accepted = 0;
		for(int i=0;i<m;i++) {
			int num = s.nextInt();
			String val = s.next();
			if (val.equals("AC")) {
				if (!ac.containsKey(num)) {
					accepted++;
					ac.put(num, val);
				}
			}else {
				if (waMap.containsKey(num+"WA")) {
					waMap.put(num+"WA", waMap.get(num+"WA") + 1);
				}else {
					waMap.put(num+"WA", 1);
				}
				if (!ac.containsKey(num)) {
					wrong++;
				}
				if (!wa.containsKey(num)) {
					wa.put(num, val);
				}
			}
		}
		for(Integer x : wa.keySet()) {
			if (!ac.containsKey(x)) {
				wrong -= waMap.get(x+"WA");
			}
		}
		System.out.println(accepted+" "+wrong);
	}
}

