			if (a[i] < b[i]) {
				ans += a[i];
				b[i] -= a[i];
				if (b[i] < a[i + 1]) {
					ans += b[i];
					a[i + 1] -= b[i];
				}else {
					ans+=a[i+1];
					a[i + 1] =0;
				}
			} else {
				ans += b[i];
			}
		}
		System.out.println(ans);    
    }
}

