public class Main {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Task solve = new Task();
        solve.solve(in, out);
        out.close();
    }

    static class Task {
        public void solve(InputReader in, PrintWriter out) {
//            int T = in.nextInt();
//            while (T-- > 0) {
            int n = in.nextInt();
            int[] a = new int[n];
            boolean flag = true;
            for (int i = 0; i < n; ++i) a[i] = in.nextInt();
            for (int i = 0; i < n; ++i) {
                flag = a[i] % 2 == 1 || a[i] % 3 == 0 || a[i] % 5 == 0;
                if (!flag) break;
            }
            out.print(flag ? "APPROVED" : "DENIED");
//            }
        }

        public int lowerBound(long[] a, long x) {
            int l = 0, r = a.length - 1, mid = (l + r) / 2;
            while (l <= r) {
                if (a[mid] >= x) r = mid;
                else l = mid + 1;
                if (l == r) {
                    if (a[l] >= x) return l;
                    else return l + 1;
                }
                mid = (l + r) / 2;
            }
            return l;
        }

        public int upperBound(long[] a, long x) {
            int l = 0, r = a.length - 1, mid = (l + r) / 2;
            while (l <= r) {
                if (a[mid] <= x) l = mid + 1;
                else r = mid;
                if (l == r) {
                    if (a[l] > x) return l;
                    else return l + 1;
                }
                mid = (l + r) / 2;
            }
            return l;
        }

        private void perm(int[] a, int cur, List<Integer> tmp, List<List<Integer>> list) {
            if (cur == a.length) {
                List<Integer> res = new ArrayList<>();
                res.addAll(tmp);
                list.add(res);
                return;
            }
            for (int i = cur; i < a.length; ++i) {
                swap(a, i, cur);
                tmp.add(a[cur]);
                perm(a, cur + 1, tmp, list);
                tmp.remove(tmp.size() - 1);
                swap(a, i, cur);
            }
        }

        public void swap(int[] a, int i, int j) {
            int t = a[i];
            a[i] = a[j];
            a[j] = t;
        }
    }

    public static class P {
        int x, y;
        P() {}
        P(int u, int v) { x = u; y = v; }
    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner inp = new Scanner(System.in);
        int n = inp.nextInt();
        int m = inp.nextInt();
        int l = inp.nextInt();

        long aMatrix[][] = new long[n][m];
        long bMatrix[][] = new long[m][l];


        // Matrix A
        for (int k = 0; k < n; k++) {
            for (int j = 0; j < m; j++) {
                aMatrix[k][j] = inp.nextInt();
            }
        }

        // Matrix B
        for (int k = 0; k < m; k++) {
            for (int j = 0; j < l; j++) {
                bMatrix[k][j] = inp.nextInt();
            }
        }

        long total[][] = matrixCalc(aMatrix, bMatrix, n, m, l);

        for (long[] item : total) {
            String s = "";
            for (long secondItem : item) {
                if (s != "") {
                    s += " ";
                }
                s += secondItem;
            }
            System.out.print(s + "\n");
        }
    }

    public static long[][] matrixCalc(long[][] aMatrix, long[][] bMatrix, int n, int m, int l) {
        long totals[][] = new long[n][l];

        long total;

        for(int i = 0; i < n; i++){
            for(int j = 0; j < l; j++){
                total = 0L;
                for(int k = 0; k < m; k++){
                    total += aMatrix[i][k]*bMatrix[k][j];
                }
                totals[i][j] = total;
            }
        }

        return totals;
    }
}

