class AtCoder {
    final int X;
    AtCoder(FastScanner sc) {
        X = sc.nextInt();
    }

    void solve(PrintWriter out) {
        int max = 0;
        for (int i = 1; i < 32; i++) {
            for (int j = 2; j < 10; j++) {
                int x = (int) Math.pow(i, j);
                if (x > X) break;
                max = Math.max(max, x);
            }
        }
        out.println(max);
    }

}

