    static class BCanYouSolveThis {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int c = in.nextInt();
            int B[] = new int[m];
            int A[] = new int[m];
            for (int i = 0; i < m; i++) {
