    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<Integer> num = new ArrayList<>();
        for (int i = 0; i < n; i++)
            num.add(sc.nextInt());
        int cnt = 0;
        int how = 0;
        for (int i = 0; i < n; i++) {
            for (int k = how; k < num.size(); k++) {
                if (num.get(k) != k + 1) {
                    num.remove(k);
                    cnt++;
