					}
					for (int j = 0; j < n - h; j++) {
						alp[j] = alp[j + h];
					}
					for (int j = 0; j < h; j++) {
						alp[n - h + j] = tmp[j];
					}
				}
				for (int i = 0; i < n; i++) {
					System.out.print(alp[i]);
				}
