class Main{
    static void sort(String[] s, int[] count){
      for(int i = 0; i < s.length; i++){
        for(int j = i+1; j < s.length; j++){
          if(count[i] < count[j]){
            int t = count[i];
            count[i] = count[j];
            count[j] = t;
            String u = s[i];
            s[i] = s[j];
            s[j] = u;
          }
          if(count[i] == count[j]){
          if (s[i].compareTo(s[j]) > 0) {
              int t = count[i];
              count[i] = count[j];
              count[j] = t;
              String u = s[i];
              s[i] = s[j];
              s[j] = u;
          }
          }
        }
      }
    }

    public static void main(String[] args) {
        Scanner stdIn = new Scanner(System.in);
        int n = stdIn.nextInt();
