public class Main {

	public static String sort( String str ){
		String r = "";
		for( char i = 'a'; i <= 'z'; i++ ){
			for( int j = 0; j < str.length(); j++ ){
				if( i == str.charAt(j) ){
					r += i;
				}
			}
		}
		return r;
	}

