     */
    private static String checksqrt(double pnum) {
        // 引数の平方根を求める
        double n = Math.sqrt(pnum);
        // 引数を平方根で割った余りが0ならば平方数
        if (pnum % n == 0) {
            return "Yes";
        } else {
            return "No";
        }
    }

}

