                int dif = x - i;
                if (dif < abs) {
                    abs = dif;
                    num = i;
                } else {
                    break;
                }
            } else if (i > x) {
                int dif = i - x;
                if (dif < abs) {
                    abs = dif;
                    num = i;
                } else {
                    break;
                }
            }
            }
        }
