public static ArrayList<Long> getDivisorList(long val){
        ArrayList<Long> list = new ArrayList<Long>(1024);
        for(long i = 1; i * i <= val; i++){
                if(val % i == 0){
                        list.add(i);
                        if(i * i != val){
                                list.add(val / i);
                        }
                }
        }
        Collections.sort(list);
        return list;
}

