			}
			if (beforeN < a && max - min < a - prospectMin) {
				max = a;
				if (min > prospectMin) {
					min = prospectMin;
				}
			}
			if (a < prospectMin) {
				prospectMin = a;
			}
			beforeN = a;
		}
