    static class ATakoyaki {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int ntc = 1;
//        ntc = in.nextInt();
            while ((ntc--) > 0) {
                int n = in.nextInt();
                int x = in.nextInt();
                int t = in.nextInt();
                int a = (n + x - 1) / x;
                out.println(a * t);
            }
        }

