                r = 1;
            } else {
                r = -1;
            }
            int cc = 0;
            for (int j = 0; j < n; j++) {
                if (a - i >= 0) {
                    if (r == 1 && h[j] - i < 0) {
                        r = -1;
                        cc++;
                    }
                    if (r == -1 && h[j] - i >= 0) {
                        r = 1;
                        cc++;
                    }
                } else {
