  }

  public static void dfs(int i, int j){

    if (N <= i) {
      count++;
      //System.out.println("OK");
      return;
    }

    //System.out.print(i + " ");

    if (j < a.length) {

      if (a[j] < i) {    

        if (j + 1 < a.length) {
          j++;
        }

        //System.out.println("jを"+j+"（"+a[j]+"）に変えます");
      }

      if (i == a[j]){
        //System.out.println(i+"の穴に落ちます");
        return;  
      }

    }

    dfs(i+1,j);

    if (i != N - 1) {
      dfs(i+2,j);
    }

  }

}

