public class Main {
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int[] h = new int[n];
        for (int i = 0; i < n; i++) {
            h[i] = sc.nextInt();
        }
        int[] dp = new int[n];
        for (int i = 0; i < n; i++) {
            dp[i] = Integer.MAX_VALUE;;
        }
        dp[0] = 0;

        for (int i = 1; i < n; i++) {
            for (int j = 1; j <= k; j++) {
                if (i > k) {
                    dp[i] = Math.min(dp[i], dp[i-k] + Math.abs(h[i] - h[i-k]));
                } else {
                    dp[i] = Math.min(dp[i], dp[i-1]+Math.abs(h[i] - h[i-1]));
                }
            }
            //System.out.println(dp[i]);
        }
        System.out.println(dp[n-1]);
    }
}

