		StringBuilder sb = new StringBuilder();

		final int B_TOTAL = 4;
		final int F_TOTAL = 3;
		final int R_TOTAL = 10;
		Room[][][] univ_rooms = new Room[B_TOTAL][F_TOTAL][R_TOTAL];

