			for (int j = 0; j < F_TOTAL; j++) {
				for (int k = 0; k < R_TOTAL; k++) {
					univ_rooms[i][j][k] = new Room(0);
				}
			}
		}

		int n = Integer.parseInt(br.readLine());
		String[] str = new String[4];
		int b, f, r, v;
