        int arr[] = in.nextIntArray(N);

        int target = 1;
        int hitCnt = 0;

        for(int i = 0; i < N; i++){
            if(arr[i] == target){
                target ++;
            } else {
                hitCnt ++;
            }
        }

        if(target == 1 && hitCnt > 0){
            out.println(-1);
        } else {
