	private static int SearchTrio(int n, int x){
		int r=0;
	    for(int i=1; i<=(n/3); i++){
	    	r += SearchPair(i, n, x-i);
		}
	    return r;
	}

	private static int SearchPair(int min, int max, int x){
		int r=0;
		for(int i=min; i<=(min + max)/2; i++){
			if( x - i < max) r++;
		}
		return r;
	}
}

