public class Main {
    private static final int MOD = (int) Math.pow(10, 9);
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) {
        FastReader sc = new FastReader();
        int n = sc.nextInt();
        long k = sc.nextLong();
        Long[] monsters = new Long[n];

        for (int i = 0; i < n; i++) {
            monsters[i] = sc.nextLong();
        }

        long res = 0;

        Arrays.sort(monsters, Collections.reverseOrder());

        for (int i = 0; i < n; i++) {
            if (k > 0) {
                k--;
            } else {
                res += monsters[i];
            }
        }

        System.out.println(res);

        System.exit(0);
    }
    static private class Point {
        public int x;
        public int y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static private int log2(int x) {
        return (int)(Math.log(x) / Math.log(2));
    }

    static private long gcd(long m, long n) {
        if (m < n) { return gcd(n, m); }
        if (m % n == 0) { return n; }
        return gcd(n, m%n);
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException  e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try{
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.*;

class Main{
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int A = sc.nextInt(),ans1 = 0,ans2 = 0;
        List<Integer> list = new ArrayList<>();
        for(int i = 0;i < A; i++){
            list.add(sc.nextInt());
        }
        Collections.sort(list);
        if(A % 2 == 0) {
            while (A >= 1) {
                ans1 += list.get(A - 1);
                ans2 += list.get(A - 2);
                A -= 2;
            }
        }else{
            while(A >= 0){
                ans1 += list.get(A-1);
                if(A == 1){
                    break;
                }
                ans2 += list.get(A-2);
                A -= 2;
            }
        }
        System.out.println(ans1-ans2);
    }
}

