          b[i][j] = in.nextInt();
        }
      }

      for (int i = 0; i < n; i++) {
        for (int j = 0; j < l; j++) {
          for (int k = 0; k < m; k++) {
            c[i][j] += a[i][k] * b[k][j];
          }
        }
      }

      for (int i = 0; i < n; i++) {
        for (int j = 0; j < l; j++) {
          out.print(c[i][j]);
          if (j != l - 1) {
            out.print(" ");
          } else {
            out.print("\n");
          }
        }
      }
//      End solve()
    }
//    End Solution
}

