    static class Task {
        public void solve(Scanner sc, PrintWriter out) {
            final StringBuffer dream = new StringBuffer("dream").reverse();
            final StringBuffer dreamer  = new StringBuffer("dreamer").reverse();
            final StringBuffer erase = new StringBuffer("erase").reverse();
            final StringBuffer eraser = new StringBuffer("eraser").reverse();
            List<StringBuffer> list = new ArrayList<>();
            list.add(dream);
            list.add(dreamer);
            list.add(erase);
            list.add(eraser);

            String S = nstr(sc);
            StringBuffer reversedS = new StringBuffer(S).reverse();
            int remain = reversedS.length();
            int i = 0;
            while (remain > 0) {
                int tmp = remain;
                for (StringBuffer str : list) {
                    String value = str.toString();
                    int valueSize = value.length();
                    if (remain < valueSize){
                        continue;
                    }
                    if (value.equals(reversedS.substring(i, i+ valueSize))) {
                        remain -= valueSize;
                        i += valueSize;
                    }
                }
                if (tmp == remain){
                    out.println("N0");
                    return;
                }
            }
            out.println("YES");


        }
