		int N = ni();
		long ans = 0;
		for (int i = 1; i <= N; i++)
			for (int j = 1; j <= N; j++) {
				long g = gcd(i, j);
				for (int k = 1; k <= N; k++)
					ans += gcd(g, k);
			}
		out.println(ans);
