			for (int j = i + 1; j <= R; j++) {
				mod = (i % 2019) * (j % 2019);
				minMod = Math.min(minMod, mod);
				if (j % 2019 == 0) break;
			}
			if (i % 2019 == 0) break;
		}

		System.out.println(minMod % 2019);
	}
}

