	// ======================================================================
	public void solve() {
		long A = nl();
		long B = nl();
		long C = nl();
		long D = nl();
		long CD = lcm(C, D);
		long ans = B - A + 1;
		ans -= (B/C - (A-1)/C);
		ans -= (B/D - (A-1)/D);
		ans += (B/CD - (A-1)/CD);
		out.println(ans);
	}
	// 最大公約数の取得
	long gcd(long a, long b) {
		if (b == 0)
			return a;
		return gcd(b, a % b);
	}

	// 最小公倍数の取得
	long lcm(long a, long b) {
		return a / gcd(a, b) * b;
	}


